<section class="panel"><h2>Authorized users</h2><table><tr><th>Name</th><th>Email</th><th>Role</th></tr><?php foreach(query('SELECT name,email,role FROM users ORDER BY name')->fetchAll() as $r): ?><tr><td><?= e($r['name']) ?></td><td><?= e($r['email']) ?></td><td><?= e($r['role']) ?></td></tr><?php endforeach ?></table></section><section class="panel"><h2>Create account</h2><?php startForm('create_user'); ?><div class="form-grid"><?php field('name','Full name'); field('email','Email','','email'); field('password','Password (at least 10 characters)','','password'); selectField('role','Role',array_map(fn($r)=>['id'=>$r,'name'=>ucfirst($r)],['admin','custodian','teacher','staff'])); ?></div><?php endForm('Create user'); ?></section>
